import { Show } from "solid-js";

export enum BadgeSize {
	BASE = "base",
	SMALL = "small",
	MINI = "mini",
	MICRO = "micro",
	DEFAULT = "default",
}

const STYLES = {
	[BadgeSize.BASE]: {
		badge: "w-20 h-20 pl-0.5",
		outerLevel: "relative w-7 h-7 left-6 -bottom-9 flex left-1/2 bottom-8",
		innerLevel: "font-fit-shrink whitespace-nowrap",
	},
	[BadgeSize.SMALL]: {
		badge: "w-16 h-16 pl-0.5",
		outerLevel: "relative -bottom-7 flex w-7 h-7 left-4",
		innerLevel: "mx-1\\.25 font-fit-shrink whitespace-nowrap",
	},
	[BadgeSize.MINI]: {
		badge: "w-20 h-20 pl-0.5",
		outerLevel: "relative w-7 h-7 left-6 -bottom-10 left-1/2 bottom-8",
		innerLevel: "font-fit-shrink whitespace-nowrap",
	},
	[BadgeSize.MICRO]: {
		badge: "w-12 h-12 justify-center",
		outerLevel: "relative w-8 h-8 -bottom-9 left-1/2 bottom-8",
		innerLevel: "",
	},
	[BadgeSize.DEFAULT]: {
		badge: "w-20 h-20",
		outerLevel: "",
		innerLevel: "",
	},
};

interface Props {
	badgeSize: BadgeSize;
	badgeUrl: string;
	progressionLevel: string;
	class?: string;
}

export const ProgressionBadge = (props: Props) => {
	const displayLevel = Network.supportsSSO();

	const style = () => STYLES[props.badgeSize] ?? STYLES[BadgeSize.DEFAULT];

	return (
		<div class={`relative flex flex-auto justify-center ${props.class || ""}`}>
			<div
				class={`flex bg-contain bg-no-repeat self-center ${style().badge}`}
				style={{ "background-image": `url('${props.badgeUrl}')` }}
			>
				<Show when={displayLevel}>
					<div
						class={`relative bg-contain bg-no-repeat self-center flex items-center justify-center ${style().outerLevel}`}
						style={{ "background-image": "url('fs://game/prof_lvl_bk.png')" }}
					>
						<div class={`font-body text-normal text-sm self-center ${style().innerLevel}`}>
							{props.progressionLevel}
						</div>
					</div>
				</Show>
			</div>
		</div>
	);
};
